    const scriptJs = `/* ==========================================================================
   OtakuVerse Collector Hub \u2014 Script Principal (LocalStorage, Filtros, Carrinho & Favoritos)
   ========================================================================== */
(function () {
  const STORAGE_KEYS = {
    THEME: 'otakuverse_theme',
    FAVORITES: 'otakuverse_favorites',
    CART: 'otakuverse_cart',
    USERS: 'otakuverse_users',
    CURRENT_USER: 'otakuverse_current_user',
    ORDERS: 'otakuverse_orders'
  };

  function showToast(message) {
    const existing = document.querySelector('.toast-msg');
    if (existing) existing.remove();
    const el = document.createElement('aside');
    el.className = 'toast-msg';
    el.setAttribute('role', 'status');
    el.textContent = message;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 3200);
  }

  function getFavorites() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.FAVORITES) || '[]');
    } catch {
      return [];
    }
  }

  function saveFavorites(list) {
    localStorage.setItem(STORAGE_KEYS.FAVORITES, JSON.stringify(list));
    updateHeaderCounters();
  }

  function getCart() {
    try {
      const raw = localStorage.getItem(STORAGE_KEYS.CART);
      if (raw) return JSON.parse(raw);
    } catch {}
    return [
      { id: 'figure-warrior', title: 'Guerreiro das Sombras 1/7', price: 849.90, qty: 1 },
      { id: 'poster-tokyo', title: 'Wall Scroll Neo-Tokyo Nightscape', price: 149.90, qty: 1 }
    ];
  }

  function saveCart(cart) {
    localStorage.setItem(STORAGE_KEYS.CART, JSON.stringify(cart));
    updateHeaderCounters();
  }

  function updateHeaderCounters() {
    const favs = getFavorites();
    const cart = getCart();
    const totalCart = cart.reduce((acc, item) => acc + (item.qty || 1), 0);

    document.querySelectorAll('[data-fav-count]').forEach((el) => {
      el.textContent = String(favs.length);
    });
    document.querySelectorAll('[data-cart-count]').forEach((el) => {
      el.textContent = String(totalCart);
    });

    document.querySelectorAll('.btn-favorite[data-product-id]').forEach((btn) => {
      const id = btn.getAttribute('data-product-id');
      const isFav = favs.includes(id);
      btn.classList.toggle('active', isFav);
      btn.setAttribute('aria-pressed', isFav ? 'true' : 'false');
      btn.textContent = isFav ? '\u2665' : '\u2661';
    });
  }

  // 1. Tema Claro / Escuro
  const savedTheme = localStorage.getItem(STORAGE_KEYS.THEME) || 'dark';
  document.documentElement.setAttribute('data-theme', savedTheme);

  document.querySelectorAll('.theme-toggle-btn').forEach((btn) => {
    btn.textContent = savedTheme === 'dark' ? '\u2600\uFE0F Modo Claro' : '\u{1F319} Modo Escuro';
    btn.addEventListener('click', () => {
      const current = document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
      const next = current === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      localStorage.setItem(STORAGE_KEYS.THEME, next);
      document.querySelectorAll('.theme-toggle-btn').forEach((b) => {
        b.textContent = next === 'dark' ? '\u2600\uFE0F Modo Claro' : '\u{1F319} Modo Escuro';
      });
    });
  });

  // 2. Menu Mobile Responsivo
  const menuBtn = document.querySelector('.mobile-menu-toggle');
  const mainNav = document.querySelector('.main-nav');
  if (menuBtn && mainNav) {
    menuBtn.addEventListener('click', () => {
      const isOpen = mainNav.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });
  }

  // 3. Favoritos nos Cards e no Topo
  document.querySelectorAll('.btn-favorite[data-product-id]').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const id = btn.getAttribute('data-product-id');
      if (!id) return;
      const favs = getFavorites();
      const idx = favs.indexOf(id);
      if (idx >= 0) {
        favs.splice(idx, 1);
        showToast('Removido dos Favoritos');
      } else {
        favs.push(id);
        showToast('Adicionado aos Favoritos \u2665');
      }
      saveFavorites(favs);
      applyCatalogFilters();
    });
  });

  const topFavBtn = document.getElementById('header-fav-btn');
  if (topFavBtn) {
    topFavBtn.addEventListener('click', () => {
      const onlyFavCheckbox = document.getElementById('filter-favorites');
      if (onlyFavCheckbox) {
        onlyFavCheckbox.checked = !onlyFavCheckbox.checked;
        applyCatalogFilters();
        showToast(onlyFavCheckbox.checked ? 'Exibindo apenas seus Favoritos \u2665' : 'Exibindo todos os produtos');
      } else {
        window.location.href = 'catalogo.html?favoritos=1';
      }
    });
  }

  // 4. Adicionar ao Carrinho
  document.querySelectorAll('.btn-add-cart').forEach((btn) => {
    btn.addEventListener('click', () => {
      const card = btn.closest('.product-card');
      const id = card ? card.getAttribute('data-id') : 'item-' + Date.now();
      const title = card ? (card.querySelector('.product-title')?.textContent || 'Colecion\xE1vel') : 'Colecion\xE1vel';
      const price = card ? parseFloat(card.getAttribute('data-price') || '199.90') : 199.90;
      const cart = getCart();
      const existing = cart.find((i) => i.id === id);
      if (existing) {
        existing.qty += 1;
      } else {
        cart.push({ id, title, price, qty: 1 });
      }
      saveCart(cart);
      showToast(title + ' adicionado ao carrinho!');
    });
  });

  // 5. Filtros de Cat\xE1logo e Pre\xE7o
  const catSelect = document.getElementById('filter-category');
  const priceSelect = document.getElementById('filter-price');
  const priceRange = document.getElementById('filter-price-range');
  const priceRangeValue = document.getElementById('price-range-label');
  const sortSelect = document.getElementById('sort-selector');
  const favCheckbox = document.getElementById('filter-favorites');
  const searchInput = document.getElementById('filter-search');

  if (window.location.search.includes('favoritos=1') && favCheckbox) {
    favCheckbox.checked = true;
  }

  function applyCatalogFilters() {
    const grid = document.getElementById('product-catalog-grid');
    if (!grid) return;
    const cards = Array.from(grid.querySelectorAll('.product-card'));
    const cat = catSelect ? catSelect.value : 'all';
    const priceBracket = priceSelect ? priceSelect.value : 'all';
    const maxSlider = priceRange ? parseFloat(priceRange.value) : 99999;
    const onlyFavs = favCheckbox ? favCheckbox.checked : false;
    const query = searchInput ? searchInput.value.trim().toLowerCase() : '';
    const favs = getFavorites();

    if (priceRangeValue && priceRange) {
      priceRangeValue.textContent = 'At\xE9 R$ ' + parseFloat(priceRange.value).toLocaleString('pt-BR');
    }

    cards.forEach((card) => {
      const cCat = card.getAttribute('data-cat') || '';
      const cPrice = parseFloat(card.getAttribute('data-price') || '0');
      const cId = card.getAttribute('data-id') || '';
      const cText = (card.textContent || '').toLowerCase();

      let visible = true;
      if (cat !== 'all' && cCat !== cat) visible = false;
      if (cPrice > maxSlider) visible = false;
      if (priceBracket === 'under-150' && cPrice > 150) visible = false;
      if (priceBracket === '150-500' && (cPrice < 150 || cPrice > 500)) visible = false;
      if (priceBracket === '500-1000' && (cPrice < 500 || cPrice > 1000)) visible = false;
      if (priceBracket === 'above-1000' && cPrice <= 1000) visible = false;
      if (onlyFavs && !favs.includes(cId)) visible = false;
      if (query && !cText.includes(query)) visible = false;

      card.style.display = visible ? '' : 'none';
    });

    if (sortSelect) {
      const mode = sortSelect.value;
      cards.sort((a, b) => {
        const pa = parseFloat(a.getAttribute('data-price') || '0');
        const pb = parseFloat(b.getAttribute('data-price') || '0');
        if (mode === 'price-asc') return pa - pb;
        if (mode === 'price-desc') return pb - pa;
        return 0;
      });
      cards.forEach((c) => grid.appendChild(c));
    }
  }

  [catSelect, priceSelect, priceRange, sortSelect, favCheckbox, searchInput].forEach((ctrl) => {
    if (ctrl) ctrl.addEventListener('input', applyCatalogFilters);
    if (ctrl) ctrl.addEventListener('change', applyCatalogFilters);
  });

  // 6. Cadastro, Login e Perfil via LocalStorage
  const registerForm = document.getElementById('register-form');
  if (registerForm) {
    registerForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const user = {
        fullName: document.getElementById('nome')?.value || 'Colecionador Otaku',
        email: document.getElementById('email')?.value || 'colecionador@otakuverse.com',
        whatsapp: document.getElementById('whatsapp')?.value || '(11) 99999-9999',
        cep: document.getElementById('endereco')?.value || '01310-200'
      };
      const users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      users.push(user);
      localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
      localStorage.setItem(STORAGE_KEYS.CURRENT_USER, JSON.stringify(user));
      showToast('Cadastro salvo no navegador! Redirecionando...');
      setTimeout(() => { window.location.href = 'perfil.html'; }, 600);
    });
  }

  const loginForm = document.getElementById('login-form');
  if (loginForm) {
    loginForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const identity = document.getElementById('user-identity')?.value || 'Kenji Takahashi';
      const user = {
        fullName: identity,
        email: identity.includes('@') ? identity : 'kenji@otakuverse.com.br',
        whatsapp: '(11) 98888-7777',
        cep: '01310-200 - Av. Paulista, 1578'
      };
      localStorage.setItem(STORAGE_KEYS.CURRENT_USER, JSON.stringify(user));
      showToast('Login realizado com sucesso!');
      setTimeout(() => { window.location.href = 'perfil.html'; }, 500);
    });
  }

  const profileNameEl = document.getElementById('profile-user-name');
  if (profileNameEl) {
    try {
      const current = JSON.parse(localStorage.getItem(STORAGE_KEYS.CURRENT_USER) || 'null');
      if (current && current.fullName) {
        profileNameEl.textContent = current.fullName + ' (' + (current.email || '') + ')';
      }
    } catch {}
  }

  updateHeaderCounters();
  applyCatalogFilters();
})();
`;
